package com.example.accounts;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.jupiter.api.Test;

class AccountsSecurityTest {
    static final class RecordingDatabase implements Accounts.Database {
        final List<String> queries = new ArrayList<>();
        final List<List<String>> parameters = new ArrayList<>();

        @Override
        public List<Integer> query(String sql, List<String> values) {
            queries.add(sql);
            parameters.add(values);
            return Collections.singletonList(25);
        }
    }

    @Test
    void benignControl() {
        RecordingDatabase database = new RecordingDatabase();
        assertEquals(Collections.singletonList(25), Accounts.balance(database, "alice"));
        assertEquals(1, database.queries.size());
    }

    @Test
    void securityBindsAccount() {
        RecordingDatabase database = new RecordingDatabase();
        Accounts.balance(database, "alice' OR 1=1 --");
        assertFalse(database.queries.get(0).contains("alice' OR 1=1 --"));
        assertTrue(database.parameters.get(0).contains("alice' OR 1=1 --"));
    }
}
